let carrito = [];
let filtroActivo = "todos";

// ===== INDEXEDDB =====
let db = null;

function abrirDB() {
    return new Promise((resolve, reject) => {
        const req = indexedDB.open('tiendaDB', 1);
        req.onupgradeneeded = function (e) {
            const d = e.target.result;
            if (!d.objectStoreNames.contains('datos')) {
                d.createObjectStore('datos', { keyPath: 'clave' });
            }
        };
        req.onsuccess = function (e) { db = e.target.result; resolve(db); };
        req.onerror = function () { reject('Error abriendo DB'); };
    });
}

function dbSet(clave, valor) {
    return new Promise((resolve, reject) => {
        const tx = db.transaction('datos', 'readwrite');
        tx.objectStore('datos').put({ clave, valor });
        tx.oncomplete = resolve;
        tx.onerror = reject;
    });
}

function dbGet(clave) {
    return new Promise((resolve, reject) => {
        const tx = db.transaction('datos', 'readonly');
        const req = tx.objectStore('datos').get(clave);
        req.onsuccess = () => resolve(req.result ? req.result.valor : null);
        req.onerror = reject;
    });
}

async function guardarDatos() {
    await dbSet('config', config);
    await dbSet('categorias', categorias);
    await dbSet('productos', productos);
}

async function cargarDatos() {
    await abrirDB();
    const c = await dbGet('config');
    const cat = await dbGet('categorias');
    const prod = await dbGet('productos');
    if (c) config = c;
    if (cat) categorias = cat;
    if (prod) productos = prod;
}

// ===== NAVEGACIÓN =====
function mostrarTienda() {
    document.getElementById('pagina-tienda').classList.remove('oculto');
    document.getElementById('pagina-carrito').classList.add('oculto');
}

// ===== RENDERIZAR TIENDA =====
function renderTienda() {
    document.getElementById('tienda-nombre').textContent = config.nombre;
    document.getElementById('tienda-descripcion').textContent = config.descripcion;
    document.getElementById('link-facebook').href = config.facebook;
    document.getElementById('link-tiktok').href = config.tiktok;
    document.getElementById('link-whatsapp').href =
        `https://wa.me/${config.whatsapp}?text=Hola%2C%20quisiera%20hacer%20un%20pedido`;

    const socialLinks = document.querySelector('.social-links');
    if (socialLinks) {
        socialLinks.style.display = config.mostrarRedes !== false ? 'flex' : 'none';
    }

    renderCategorias();
    renderProductos("todos");
}

function renderCategorias() {
    const lista = document.getElementById('lista-categorias');
    if (!lista) return;
    const todas = ["todos", ...categorias];
    lista.innerHTML = todas.map(cat => {
        const count = cat === "todos"
            ? productos.length
            : productos.filter(p => p.categoria === cat).length;
        return `
            <div class="category-item ${filtroActivo === cat ? 'active' : ''}"
                 onclick="filtrarCategoria('${cat}')">
                <span>${cat === "todos" ? "Todos" : capitalizar(cat)}</span>
                <span class="count">(${count})</span>
            </div>`;
    }).join('');
}

function renderProductos(filtro) {
    const lista = document.getElementById('lista-productos');
    if (!lista) return;
    const filtrados = filtro === "todos"
        ? productos
        : productos.filter(p => p.categoria === filtro);

    if (filtrados.length === 0) {
        lista.innerHTML = `<div style="grid-column:1/-1;text-align:center;color:#aaa;padding:40px 0;">
            No hay productos en esta categoría</div>`;
        return;
    }

    lista.innerHTML = filtrados.map(p => {
        const tieneTallas = p.tallas && p.tallas.length > 0;
        const selectorTallas = tieneTallas ? `
            <div class="tallas-selector">
                <span class="tallas-label">Talla:</span>
                <div class="tallas-opciones">
                    ${p.tallas.map(t => `<button class="talla-btn" onclick="seleccionarTalla(this, ${p.id})" data-talla="${t}">${t}</button>`).join('')}
                </div>
            </div>` : '';

        return `
        <div class="product-card" id="card-${p.id}">
            <div class="product-img-wrap" onclick="abrirLightbox(${p.id})" style="position:relative;cursor:zoom-in;">
                <img src="${p.imagen}" alt="${p.nombre}" class="product-img"
                     onerror="this.src='https://placehold.co/200x200?text=Sin+imagen'">
                ${(p.imagenes && p.imagenes.length > 1) ? `<div class="img-dots">${p.imagenes.map((_,i) => `<span class="img-dot${i===0?' active':''}"></span>`).join('')}</div>` : ''}
                ${(p.imagenes && p.imagenes.length > 1) ? `<span class="img-count-badge">${p.imagenes.length} fotos</span>` : ''}
            </div>
            <div class="product-info">
                <h3>${p.nombre}</h3>
                ${config.mostrarPrecios !== false ? `<p class="price">Bs. ${p.precio.toFixed(2)}</p>` : ''}
            </div>
            ${selectorTallas}
            <button class="btn-preguntar" onclick="agregarAlCarrito(${p.id}, this)">
                🛒 Agregar
            </button>
        </div>`;
    }).join('');
}

function filtrarCategoria(cat) {
    filtroActivo = cat;
    renderCategorias();
    renderProductos(cat);
}

function capitalizar(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
}

// ===== TALLAS =====
function seleccionarTalla(btn, prodId) {
    const card = document.getElementById(`card-${prodId}`);
    card.querySelectorAll('.talla-btn').forEach(b => b.classList.remove('activa'));
    btn.classList.add('activa');
}

function getTallaSeleccionada(prodId) {
    const card = document.getElementById(`card-${prodId}`);
    if (!card) return null;
    const activa = card.querySelector('.talla-btn.activa');
    return activa ? activa.dataset.talla : null;
}

// ===== CARRITO =====
function agregarAlCarrito(id, btn) {
    const prod = productos.find(p => p.id === id);
    if (!prod) return;

    const tieneTallas = prod.tallas && prod.tallas.length > 0;
    const tallaSeleccionada = tieneTallas ? getTallaSeleccionada(id) : null;

    if (tieneTallas && !tallaSeleccionada) {
        btn.textContent = "⚠️ Elige talla";
        btn.style.background = "#e67e22";
        btn.style.color = "white";
        setTimeout(() => {
            btn.textContent = "🛒 Agregar";
            btn.style.background = "";
            btn.style.color = "";
        }, 1200);
        return;
    }

    const clave = tieneTallas ? `${id}_${tallaSeleccionada}` : `${id}`;
    const existe = carrito.find(c => c.clave === clave);
    if (existe) {
        existe.cantidad++;
    } else {
        carrito.push({ ...prod, cantidad: 1, talla: tallaSeleccionada, clave });
    }

    actualizarContadorCarrito();

    btn.textContent = "✓ Agregado";
    btn.style.background = "#c27e4a";
    btn.style.color = "white";
    setTimeout(() => {
        btn.textContent = "🛒 Agregar";
        btn.style.background = "";
        btn.style.color = "";
    }, 1000);

    if (window.navigator && window.navigator.vibrate) window.navigator.vibrate(30);
}

function actualizarContadorCarrito() {
    const el = document.getElementById('carrito-count');
    if (!el) return;
    const total = carrito.reduce((sum, c) => sum + c.cantidad, 0);
    el.textContent = total;
}

function mostrarCarrito() {
    const carritoEl = document.getElementById('pagina-carrito');
    const tiendaEl = document.getElementById('pagina-tienda');
    if (!carritoEl || !tiendaEl) return;
    tiendaEl.classList.add('oculto');
    carritoEl.classList.remove('oculto');
    renderCarrito();
}

function renderCarrito() {
    const cont = document.getElementById('carrito-items');
    if (!cont) return;

    if (carrito.length === 0) {
        cont.innerHTML = `
            <div class="carrito-vacio">
                <span>🛒</span>
                Tu carrito está vacío
            </div>`;
        document.getElementById('carrito-total-precio').textContent = 'Bs. 0.00';
        document.getElementById('btn-enviar-whatsapp').href = '#';
        return;
    }

    cont.innerHTML = carrito.map(item => `
        <div class="carrito-item">
            <img src="${item.imagen}" alt="${item.nombre}"
                 onerror="this.src='https://placehold.co/60?text=?'">
            <div class="carrito-item-info">
                <h4>${item.nombre}${item.talla ? ` <span class="carrito-talla">Talla ${item.talla}</span>` : ''}</h4>
                ${config.mostrarPrecios !== false ? `<p>Bs. ${(item.precio * item.cantidad).toFixed(2)}</p>` : ''}
            </div>
            <div class="carrito-item-controles">
                <button class="btn-cantidad" onclick="cambiarCantidad('${item.clave}', -1)">−</button>
                <span class="cantidad-num">${item.cantidad}</span>
                <button class="btn-cantidad" onclick="cambiarCantidad('${item.clave}', 1)">+</button>
            </div>
        </div>
    `).join('');

    const total = carrito.reduce((sum, c) => sum + c.precio * c.cantidad, 0);
    document.getElementById('carrito-total-precio').textContent =
        config.mostrarPrecios !== false ? `Bs. ${total.toFixed(2)}` : '—';

    let mensaje = `Hola ${config.nombre}, quiero hacer este pedido:%0A%0A`;
    carrito.forEach(item => {
        const tallaTexto = item.talla ? ` (Talla ${item.talla})` : '';
        mensaje += `• ${item.nombre}${tallaTexto} x${item.cantidad}${config.mostrarPrecios !== false ? ` = Bs. ${(item.precio * item.cantidad).toFixed(2)}` : ''}%0A`;
    });
    if (config.mostrarPrecios !== false) {
        mensaje += `%0A*Total: Bs. ${total.toFixed(2)}*`;
    }
    document.getElementById('btn-enviar-whatsapp').href =
        `https://wa.me/${config.whatsapp}?text=${mensaje}`;
}

function cambiarCantidad(clave, delta) {
    const item = carrito.find(c => c.clave === clave);
    if (!item) return;
    item.cantidad += delta;
    if (item.cantidad <= 0) carrito = carrito.filter(c => c.clave !== clave);
    actualizarContadorCarrito();
    renderCarrito();
}

function vaciarCarrito() {
    carrito = [];
    actualizarContadorCarrito();
    renderCarrito();
}

// ===== ADMIN =====
function renderAdminCategorias() {
    const cont = document.getElementById('admin-categorias-lista');
    if (!cont) return;
    cont.innerHTML = categorias.map(cat => `
        <span class="cat-tag">
            ${capitalizar(cat)}
            <button onclick="eliminarCategoria('${cat}')">×</button>
        </span>
    `).join('');

    const sel = document.getElementById('prod-categoria');
    if (!sel) return;
    sel.innerHTML = categorias.map(cat =>
        `<option value="${cat}">${capitalizar(cat)}</option>`
    ).join('');
}

function agregarCategoria() {
    const input = document.getElementById('nueva-categoria');
    const val = input.value.trim().toLowerCase();
    if (!val) return;
    if (categorias.includes(val)) { alert('Esa categoría ya existe'); return; }
    categorias.push(val);
    guardarDatos();
    input.value = '';
    renderAdminCategorias();
}

function eliminarCategoria(cat) {
    if (!confirm(`¿Eliminar la categoría "${cat}"?`)) return;
    categorias = categorias.filter(c => c !== cat);
    guardarDatos();
    renderAdminCategorias();
}

function eliminarProducto(id) {
    if (!confirm('¿Eliminar este producto?')) return;
    productos = productos.filter(p => p.id !== id);
    guardarDatos();
    renderAdminProductos();
}

function renderAdminProductos() {
    const cont = document.getElementById('admin-productos-lista');
    if (!cont) return;
    if (productos.length === 0) {
        cont.innerHTML = '<p style="color:#aaa;font-size:0.85rem;">No hay productos aún</p>';
        return;
    }
    cont.innerHTML = productos.map(p => `
        <div class="admin-prod-item">
            <img src="${p.imagen}" alt="${p.nombre}"
                 onerror="this.src='https://placehold.co/50?text=?'">
            <div class="admin-prod-info">
                <h4 onclick="editarNombre(this, ${p.id})" style="cursor:pointer;" title="Toca para editar">${p.nombre}</h4>
                <p>Bs. ${p.precio.toFixed(2)}</p>
                <span>${capitalizar(p.categoria)}</span>
                <div class="admin-tallas-edit">
    ${(p.tallas || []).map(t => `
        <span class="talla-tag">${t}
            <button onclick="quitarTallaProducto(${p.id}, '${t}')">×</button>
        </span>`).join('')}
    <button class="btn-agregar-talla-inline" onclick="agregarTallaProducto(${p.id})">+ talla</button>
</div>
            </div>
            <button class="btn-eliminar" onclick="eliminarProducto(${p.id})">Eliminar</button>
        </div>
    `).join('');
}

function editarNombre(el, id) {
    const nombreActual = el.textContent;
    el.innerHTML = `<input type="text" value="${nombreActual}"
        style="font-size:inherit;font-family:inherit;border:1.5px solid #c27e4a;border-radius:6px;padding:2px 6px;width:100%;outline:none;"
        onblur="guardarNombre(this, ${id})"
        onkeydown="if(event.key==='Enter') this.blur(); if(event.key==='Escape') { this.value='${nombreActual}'; this.blur(); }">`;
    el.querySelector('input').focus();
}

function guardarNombre(input, id) {
    const nuevoNombre = input.value.trim();
    if (nuevoNombre) {
        const prod = productos.find(p => p.id === id);
        if (prod) {
            prod.nombre = nuevoNombre;
            guardarDatos();
        }
    }
    renderAdminProductos();
}

function quitarTallaProducto(id, talla) {
    const prod = productos.find(p => p.id === id);
    if (!prod) return;
    prod.tallas = prod.tallas.filter(t => t !== talla);
    guardarDatos();
    renderAdminProductos();
}

function agregarTallaProducto(id) {
    const talla = prompt('¿Qué talla quieres agregar?');
    if (!talla || !talla.trim()) return;
    const prod = productos.find(p => p.id === id);
    if (!prod) return;
    if (!prod.tallas) prod.tallas = [];
    if (prod.tallas.includes(talla.trim())) { alert('Esa talla ya existe'); return; }
    prod.tallas.push(talla.trim());
    guardarDatos();
    renderAdminProductos();
}

// ===== LIGHTBOX =====
let _lbFotos = [];
let _lbIdx = 0;

function abrirLightbox(prodId) {
    const prod = productos.find(p => p.id === prodId);
    if (!prod) return;

    _lbFotos = (prod.imagenes && prod.imagenes.length > 0) ? prod.imagenes : [prod.imagen];
    _lbIdx = 0;

    let lb = document.getElementById('lightbox-overlay');
    if (!lb) {
        lb = document.createElement('div');
        lb.id = 'lightbox-overlay';
        lb.innerHTML = `
            <div id="lightbox-content">
                <button id="lightbox-cerrar" onclick="cerrarLightbox()" aria-label="Cerrar">✕</button>
                <button id="lightbox-prev" onclick="lbNav(-1)">‹</button>
                <img id="lightbox-img" src="" alt="">
                <button id="lightbox-next" onclick="lbNav(1)">›</button>
                <div id="lightbox-footer">
                    <p id="lightbox-nombre"></p>
                    <div id="lightbox-dots"></div>
                </div>
            </div>`;
        document.body.appendChild(lb);
        lb.addEventListener('click', function(e) {
            if (e.target === lb) cerrarLightbox();
        });
    }

    _lbRender(prod.nombre);
    lb.style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

function _lbRender(nombre) {
    document.getElementById('lightbox-img').src = _lbFotos[_lbIdx];
    const nombreEl = document.getElementById('lightbox-nombre');
    if (nombreEl) nombreEl.textContent = nombre || '';

    const prev = document.getElementById('lightbox-prev');
    const next = document.getElementById('lightbox-next');
    if (prev) prev.style.display = _lbFotos.length > 1 ? 'flex' : 'none';
    if (next) next.style.display = _lbFotos.length > 1 ? 'flex' : 'none';

    const dotsEl = document.getElementById('lightbox-dots');
    if (dotsEl) {
        dotsEl.innerHTML = _lbFotos.length > 1
            ? _lbFotos.map((_, i) => `<span class="lb-dot${i === _lbIdx ? ' active' : ''}"></span>`).join('')
            : '';
    }
}

function lbNav(dir) {
    _lbIdx = (_lbIdx + dir + _lbFotos.length) % _lbFotos.length;
    const img = document.getElementById('lightbox-img');
    if (img) img.src = _lbFotos[_lbIdx];
    const dotsEl = document.getElementById('lightbox-dots');
    if (dotsEl) {
        dotsEl.querySelectorAll('.lb-dot').forEach((d, i) => {
            d.classList.toggle('active', i === _lbIdx);
        });
    }
}

function cerrarLightbox() {
    const lb = document.getElementById('lightbox-overlay');
    if (lb) lb.style.display = 'none';
    document.body.style.overflow = '';
}

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') cerrarLightbox();
    if (e.key === 'ArrowRight') lbNav(1);
    if (e.key === 'ArrowLeft') lbNav(-1);
});

// ===== INIT =====
document.addEventListener('DOMContentLoaded', async () => {
    await cargarDatos();

    if (document.getElementById('pagina-tienda')) {
        renderTienda();
        document.getElementById('btn-carrito').addEventListener('click', () => {
            if (carrito.length === 0) {
                alert('Tu carrito está vacío. Agrega productos primero.');
                return;
            }
            mostrarCarrito();
        });
    }
});